// 1日キャッシュする静的コンテンツ
export async function StaticContent() {
  'use cache';
  cacheLife('days');
  cacheTag('static-content');

  const data = await fetchStaticData();
  return <div>{data}</div>;
}

// 1時間キャッシュする商品一覧
export async function ProductList() {
  'use cache';
  cacheLife('hours');
  cacheTag('products');

  const products = await fetchProducts();
  return (
    <ul>
      {products.map(p => <li key={p.id}>{p.name}</li>)}
    </ul>
  );
}

// 5分キャッシュするユーザープロフィール
export async function UserProfile({ userId }: { userId: string }) {
  'use cache';
  cacheLife('minutes');
  cacheTag('user', `user-${userId}`);

  const user = await fetchUser(userId);
  return <div>{user.name}</div>;
}

// 5秒キャッシュするリアルタイムデータ
export async function RealtimeData() {
  'use cache';
  cacheLife('seconds');
  cacheTag('realtime');

  const data = await fetchRealtimeData();
  return <div>{data}</div>;
}

// Server Action内でキャッシュを即座に無効化
import { updateTag } from 'next/cache';

export async function updateProduct(id: string, data: ProductData) {
  await saveProduct(id, data);
  // ユーザー操作直後に即座に反映が必要
  updateTag('products', `product-${id}`);
}

// Server Action内で次回リクエスト時に無効化
import { revalidateTag } from 'next/cache';

export async function updateStaticContent(id: string, data: ContentData) {
  await saveContent(id, data);
  // 次回リクエスト時の反映で問題ない
  revalidateTag('static-content', `content-${id}`);
}

// 動的部分をSuspenseでラップして分離
export default function Page() {
  return (
    <div>
      <StaticHeader /> {/* キャッシュされた静的部分 */}
      <Suspense fallback={<Loading />}>
        <DynamicContent /> {/* 動的部分 */}
      </Suspense>
    </div>
  );
}

async function StaticHeader() {
  'use cache';
  cacheLife('days');
  const data = await fetchStaticData();
  return <header>{data}</header>;
}

async function DynamicContent() {
  // キャッシュなし（動的レンダリング）
  const data = await fetchDynamicData();
  return <div>{data}</div>;
}
